package com.collegewise.entity;
import jakarta.persistence.*;
@Entity @Table(indexes=@Index(name="idx_cutoff_exam_year",columnList="entrance_exam,exam_year"))
public class Cutoff { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private College college; @ManyToOne(fetch=FetchType.LAZY) private Course course; @ManyToOne(fetch=FetchType.LAZY) private Branch branch; @Column(name="entrance_exam",nullable=false,length=50) private String entranceExam; @Column(name="exam_year",nullable=false) private Integer examYear; @Column(length=40) private String category; private Integer closingRank; private Double closingPercentile; protected Cutoff(){} public Cutoff(College c,Course course,Branch branch,String exam,Integer year,String category,Integer rank,Double percentile){this.college=c;this.course=course;this.branch=branch;this.entranceExam=exam;this.examYear=year;this.category=category;this.closingRank=rank;this.closingPercentile=percentile;} public Long getId(){return id;} public College getCollege(){return college;} public Course getCourse(){return course;} public Branch getBranch(){return branch;} public String getEntranceExam(){return entranceExam;} public Integer getExamYear(){return examYear;} public String getCategory(){return category;} public Integer getClosingRank(){return closingRank;} public Double getClosingPercentile(){return closingPercentile;} public void updateFrom(Cutoff c){this.college=c.college;this.course=c.course;this.branch=c.branch;this.entranceExam=c.entranceExam;this.examYear=c.examYear;this.category=c.category;this.closingRank=c.closingRank;this.closingPercentile=c.closingPercentile;} }
